#!/usr/bin/env python3
"""Read March receipts from the receipts/ folder and produce march_expenses.csv."""

import os
import re
import glob

from axiom_engines import time, money, table


def categorize_shop(shop: str) -> str:
    """Decide the category for a receipt based on the shop name. This is judgement."""
    s = shop.strip().lower()
    if any(w in s for w in ("grocer", "food", "market", "deli")):
        return "food"
    if any(w in s for w in ("transit", "metro", "bus", "train", "taxi", "uber", "rail")):
        return "transport"
    if any(w in s for w in ("hardware", "home", "furniture", "linen", "lamp", "garden", "plumb")):
        return "home"
    return "other"


def parse_date_line(text: str, year: int) -> str:
    """Extract and parse the date from a receipt's text."""
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    for ln in lines:
        low = ln.lower()
        if "march" in low:
            idx = low.find("march")
            snippet = ln[idx:]
            m = re.search(r'March\s+(\d{1,2}),?\s+(\d{4})', snippet)
            if m:
                return time.parse_date(f"March {m.group(1)}, {m.group(2)}", year)
        m = re.search(r'(\d{1,2})/(\d{1,2})/(\d{4})', ln)
        if m:
            return time.parse_numeric_date(m.group(0), "MDY")
    raise ValueError(f"No date found in receipt text:\n{text}")


def parse_amount(text: str) -> str:
    """Extract the total amount from a receipt."""
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    # Look for a line that is specifically "Total" (not subtotal/tax)
    for ln in lines:
        low = ln.lower().strip()
        if re.match(r'^total\s*[\$]?[\d,]+\.\d{2}$', low) or re.match(r'^total$', low):
            m = re.search(r'[\$]?([\d,]+\.\d{2})', ln)
            if m:
                return money.parse_amount(m.group(1))
    # Otherwise the last numeric line (the grand total)
    for ln in reversed(lines):
        m = re.search(r'[\$]?([\d,]+\.\d{2})', ln)
        if m:
            return money.parse_amount(m.group(1))
    raise ValueError(f"No amount found in receipt text:\n{text}")


def parse_shop(text: str) -> str:
    """Extract the shop name (first meaningful line)."""
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    for ln in lines:
        low = ln.lower()
        if low.startswith("***"):
            return ln.strip("*").strip()
        if re.search(r'(\d{1,2})/(\d{1,2})/(\d{4})', ln):
            continue
        if "march" in low or "paid on" in low:
            continue
        if re.search(r'(subtotal|tax|total|thank you|by card)', low):
            continue
        return ln
    return lines[0] if lines else ""


def main():
    receipts_dir = os.path.join(os.path.dirname(__file__), "receipts")
    year = 2026

    rows = []
    for path in sorted(glob.glob(os.path.join(receipts_dir, "*.txt"))):
        base = os.path.basename(path)
        if base.lower() == "readme.txt":
            continue
        with open(path) as f:
            text = f.read()
        shop = parse_shop(text)
        date = parse_date_line(text, year)
        amount = parse_amount(text)
        category = categorize_shop(shop)
        rows.append({
            "date": date,
            "shop": shop,
            "amount": money.format_amount(amount),
            "category": category,
        })

    rows.sort(key=lambda r: (r["date"], r["shop"]))

    table.write_csv("march_expenses.csv", ["date", "shop", "amount", "category"], rows)
    print(f"Wrote {len(rows)} rows to march_expenses.csv")


if __name__ == "__main__":
    main()
